#include <bits/stdc++.h>
#define err(...) {}
#ifdef DEBUG
#include "_debug.cpp"
#include "callable.hpp/callable.hpp"
#endif
#define endl '\n'
using namespace std;
using llong = long long;
const int MAX_SIZE = 10;
char board[MAX_SIZE][MAX_SIZE];
int people[MAX_SIZE][MAX_SIZE];
int helpers[MAX_SIZE][MAX_SIZE];
int burn[MAX_SIZE][MAX_SIZE];
const int dr[4] = {-1, 1, 0, 0};
const int dc[4] = {0, 0, -1, 1};
int dist[MAX_SIZE][MAX_SIZE][MAX_SIZE][MAX_SIZE];
const int NODES = 2 * MAX_SIZE * MAX_SIZE + 2;
const int BIG = 1000000000;
vector<int> edges[NODES + 1];
int cap[NODES + 1][NODES + 1], f[NODES + 1][NODES + 1];
int level[NODES + 1], par[NODES + 1], pos[NODES + 1];

bool bfs_level(int src, int dst) {
    fill(level, level + NODES + 1, -1);
    level[src] = 0;
    queue<int> q;
    q.push(src);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v : edges[u]) {
            if (cap[u][v] - f[u][v] > 0 && level[v] == -1) {
                level[v] = level[u] + 1;
                q.push(v);
            }
        }
    }
    return level[dst] != -1;
}

bool dfs_flow(int u, int dst) {
    if (u == dst) return true;
    for (int& i = pos[u]; i < (int)edges[u].size(); ++i) {
        int v = edges[u][i];
        if (level[v] == level[u] + 1 && cap[u][v] - f[u][v] > 0 && dfs_flow(v, dst)) {
            par[v] = u;
            return true;
        }
    }
    return false;
}

bool find_path(int src, int dst) {
    fill(par, par + NODES + 1, -1);
    par[src] = 0;
    return dfs_flow(src, dst);
}

void clear_flow() {
    memset(cap, 0, sizeof cap);
    memset(f, 0, sizeof f);
}

void link(int u, int v, int w) {
    edges[u].push_back(v);
    edges[v].push_back(u);
    cap[u][v] += w;
}

int dinic(int src, int dst) {
    int result = 0;
    while (bfs_level(src, dst)) {
        fill(pos, pos + NODES + 1, 0);
        while (find_path(src, dst)) {
            int min_cap = BIG;
            for (int v = dst, u = par[v]; v != src; v = u, u = par[v]) {
                min_cap = min(min_cap, cap[u][v] - f[u][v]);
            }
            for (int v = dst, u = par[v]; v != src; v = u, u = par[v]) {
                f[u][v] += min_cap;
                f[v][u] -= min_cap;
            }
            result += min_cap;
        }
    }
    return result;
}

int id(int sz, int r, int c, bool right) {
    return r * sz + c + (right ? sz * sz : 0);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, T;
    cin >> n >> T;
    string s;
    pair<int, int> start;
    for (int i = 0; i < n; ++i) {
        cin >> s;
        for (int j = 0; j < n; ++j) {
            if (s[j] == 'Y') {
                board[i][j] = 'Y';
            } else if (s[j] == 'Z') {
                board[i][j] = 'Z';
                start = {i, j};
            } else {
                board[i][j] = '.';
                people[i][j] += s[j] - '0';
            }
        }
    }
    for (int i = 0; i < n; ++i) {
        cin >> s;
        for (int j = 0; j < n; ++j) {
            if (s[j] != 'Y' && s[j] != 'Z') {
                helpers[i][j] += s[j] - '0';
            }
        }
    }
    memset(burn, -1, sizeof burn);
    burn[start.first][start.second] = 0;
    queue<pair<int, int>> q;
    q.push(start);
    while (!q.empty()) {
        int x = q.front().first, y = q.front().second;
        q.pop();
        for (int k = 0; k < 4; ++k) {
            int nx = x + dr[k], ny = y + dc[k];
            if (0 <= nx && nx < n && 0 <= ny && ny < n && board[nx][ny] == '.' && burn[nx][ny] == -1) {
                burn[nx][ny] = burn[x][y] + 1;
                q.push({nx, ny});
            }
        }
    }
    memset(dist, -1, sizeof dist);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (board[i][j] == '.') {
                dist[i][j][i][j] = 0;
                queue<pair<int, int>> bfs;
                bfs.push({i, j});
                while (!bfs.empty()) {
                    int r = bfs.front().first, c = bfs.front().second;
                    bfs.pop();
                    if (burn[r][c] == -1 || dist[i][j][r][c] < burn[r][c]) {
                        for (int k = 0; k < 4; ++k) {
                            int nr = r + dr[k], nc = c + dc[k];
                            if (0 <= nr && nr < n && 0 <= nc && nc < n && board[nr][nc] == '.' &&
                                (burn[nr][nc] == -1 || dist[i][j][r][c] + 1 <= burn[nr][nc]) &&
                                dist[i][j][nr][nc] == -1) {
                                dist[i][j][nr][nc] = dist[i][j][r][c] + 1;
                                bfs.push({nr, nc});
                            }
                        }
                    }
                }
            }
        }
    }
    int source = 2 * n * n, sink = 2 * n * n + 1;
    clear_flow();
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (people[i][j]) {
                link(source, id(n, i, j, false), people[i][j]);
            }
            if (helpers[i][j]) {
                link(id(n, i, j, true), sink, helpers[i][j]);
            }
            for (int ri = 0; ri < n; ++ri) {
                for (int rj = 0; rj < n; ++rj) {
                    if (dist[i][j][ri][rj] != -1 && dist[i][j][ri][rj] <= T) {
                        link(id(n, i, j, false), id(n, ri, rj, true), BIG);
                    }
                }
            }
        }
    }
    cout << dinic(source, sink) << endl;
    return 0;
}
